INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_cf704e565fc74ebbbaa447c8d7018ae4', 'content-rules-platform-v12', 'FRM11', '工艺展示组合型', 'core', '["decoration"]', '根据本次真实资料选择并冻结标题与正文组合；仅要求选中组合需要的事实。', '["施工现场", "工艺展示"]', '[]', '{"business_modes": ["J", "K"]}', '["persona_fact", "process"]', '["只使用本次已确认资料，不借用示例中的数字、工期、结果或业主故事", "计划、做事原则和已完成事实必须区分", "标准或验收结论仅在有明确依据时使用，不把标签、图片地址当作证明"]', true, 10);
