INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_256bd7708a334b9bac2725d176a9f61c', 'content-rules-platform-v8', 'FRM06', '项目单价型', 'core', '["decoration"]', '按具体施工项目展示真实单价、适用条件和包含范围，帮助业主判断报价。', '["人工工价行情", "单项人工价格"]', '["{location}{project}怎么收费，先看单价和包含范围"]', '{"business_mode": "F", "price_basis": ["standard_unit_price", "project_quote"]}', '["location", "product", "title_price"]', '["标准单价必须明确标注为参考", "标准单价不得冒充本案成交或结算价格", "不得倒推工程量或小计"]', true, 5);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_d325102880b84010ad2954a86c933d06', 'content-rules-platform-v8', 'FRM07', '单价+面积型', 'core', '["decoration"]', '在面积与单价均为同一真实口径时展示计算过程、重点项目和总价。', '["卫生间", "厨房", "局部翻新", "按面积计价"]', '["{location}{area}{business}，按{price}计算"]', '{"business_mode": "G", "calculation": "deterministic"}', '["location", "quantity", "product", "title_price"]', '["面积、单价和总价必须是同一项目口径", "计算不一致时阻断发布", "标准单价不可直接乘以项目面积推导成交总价"]', true, 6);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_4314906dbaf14fa6900c5a13c64d20f4', 'content-rules-platform-v8', 'FRM08', '工种总价型', 'core', '["decoration"]', '以真实总价为钩子，按工种说明包含项和预算分配。', '["半包", "硬装", "全屋基础施工"]', '["{location}{area}{business}，各工种总价这样分"]', '{"business_mode": "H", "evidence": ["工种总价", "包含项"]}', '["location", "quantity", "product", "title_price"]', '["各工种总价必须来自同一真实报价", "合计不一致时阻断发布", "不得补造未提供的分项"]', true, 7);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_a8205ab88fb842e3bbe70976a82cc780', 'content-rules-platform-v8', 'FRM09', '人工+辅材型', 'core', '["decoration"]', '把人工与辅材拆开说明，再按工种解释花费原因和透明服务价值。', '["半包", "硬装", "真实账单"]', '["这份{business}总价里，人工和辅材分别花在哪"]', '{"business_mode": "I", "evidence": ["人工合计", "辅材合计", "工种拆分"]}', '["product", "title_price", "process"]', '["人工、辅材和总价必须来自同一真实报价", "合计不一致时阻断发布", "透明优势必须有服务证据"]', true, 8);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_3bc7916916564a6894813b8aa26ad4ef', 'content-rules-platform-v9', 'FRM01', '价格营销型', 'core', '["decoration"]', '以真实价格或报价口径吸引注意，再解释费用构成、服务边界和工长价值。', '["施工报价", "半包报价", "毛坯房装修"]', '["{location}{business}，这份{quote_type}先把钱花在哪讲清楚"]', '{"business_mode": "A", "evidence": ["真实报价", "报价口径"]}', '["location", "product", "price"]', '["价格必须来自用户确认或已核验资料", "必须说明报价类型和包含范围", "不得把预算写成成交或结算价"]', true, 0);
INSERT INTO public.content_creation_methods (id, version_id, code, name, method_type, industry_scope, principle, suitable_scenes, sentence_patterns, tag_schema, variable_schema, risk_rules, enabled, sort_order) VALUES ('crm_89bac63b829d46098447cb266a505818', 'content-rules-platform-v9', 'FRM02', '案例故事型', 'core', '["decoration"]', '从真实业主问题和需求出发，用解决过程、施工证据与结果建立信任。', '["旧房改造", "老破小", "局部翻新", "典型案例", "日常工作"]', '["这次{location}{house}，先解决的是{needs}"]', '{"business_mode": "B", "evidence": ["案例背景", "施工过程", "结果"]}', '["location", "product", "pain", "process", "result"]', '["不得虚构业主、需求、对话、过程或反馈", "计划中的结果不得写成已经完成"]', true, 1);
